import React from "react";
import classes from './Products.module.css';
import ProductForm from "./ProductForm";

const Product_Items = [
    {
      id: "1",
      name: " Blue Jockey ",
      description: "80 % cotton 20 % polyster",
      price: 500.0,
      large:100,
      medium:80,
      small:10

    },
    {
      id: "2",
      name: " Neavy Blue Armani",
      description: "100 % cotton",
      price: 1299.0,
      large:100,
      medium:80,
      small:10
    },
    {
      id: "3",
      name: "Blue Gucci",
      description: "100 % cotton ",
      price: 1399.0,
      large:100,
      medium:80,
      small:10
    },
   
   
  ];

const Products=()=>{
    const clotheItems = Product_Items.map((item) => (
        <div key={item.id} className={classes.dish}>
          <div className={classes.category1} >Tshirt Name :{item.name}</div>
          <div className={classes.category2} >descriptiob :{item.description}</div>
          <div className={classes.category3}> Price : Rs {item.price}</div>
          <div className={classes.category4}>
            <div className={classes['quantity-box']}>L {item.large}</div>
            <div className={classes['quantity-box']}>M {item.medium}</div>
            <div className={classes['quantity-box']}>S {item.small}</div>
          </div>
          <div className={classes.form}>
            <ProductForm
                 items={item}
                 ></ProductForm>
          </div>
        </div>
      ));
    
    return(
        <div className={classes.outer}>
        {clotheItems}
      </div>
    )
}
export default Products;
